"""Caller-owned workspace for packed GDN prefill."""

from dataclasses import dataclass

import torch


def _packed_prefill_prepare_inputs_have_supported_layout(
    mixed_qkv: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    *,
    num_k_heads: int,
    num_v_heads: int,
    head_dim: int,
) -> bool:
    """Accept only contiguous or production Qwen symbolic-stride inputs."""

    if mixed_qkv.ndim != 3 or a.ndim != 3 or b.ndim != 3:
        return False
    tokens = int(mixed_qkv.shape[1])
    packed_dim = (2 * num_k_heads + num_v_heads) * head_dim
    projection_stride = (
        2 * (num_k_heads + num_v_heads) * head_dim + 2 * num_v_heads
    )
    if (
        mixed_qkv.shape != (1, tokens, packed_dim)
        or a.shape != (1, tokens, num_v_heads)
        or b.shape != a.shape
    ):
        return False
    mixed_qwen_stride = (tokens * packed_dim, 1, tokens)
    gate_qwen_stride = (tokens * projection_stride, projection_stride, 1)
    return (
        mixed_qkv.is_contiguous() or mixed_qkv.stride() == mixed_qwen_stride
    ) and (
        a.is_contiguous() or a.stride() == gate_qwen_stride
    ) and (
        b.is_contiguous() or b.stride() == gate_qwen_stride
    )


def active_token_prefix(tensor: torch.Tensor, tokens: int) -> torch.Tensor:
    # Batch is statically one, so its stride is semantically unused. Rebase it
    # to the active extent so the AOT memref exactly matches a contiguous
    # exact-T tensor without copying the capacity-backed storage.
    shape = (1, tokens, *tensor.shape[2:])
    stride = (tokens * tensor.stride(1), *tensor.stride()[1:])
    return tensor.as_strided(shape, stride)


@dataclass(frozen=True)
class PackedGatedDeltaPrefillWorkspace:
    query: torch.Tensor
    key: torch.Tensor
    value: torch.Tensor
    out: torch.Tensor
    log_g: torch.Tensor
    beta_bf16: torch.Tensor
    beta_fp32: torch.Tensor | None = None

    @property
    def capacity_tokens(self) -> int:
        return int(self.query.shape[1]) if self.query.ndim == 4 else 0

    def for_tokens(self, tokens: int) -> "PackedGatedDeltaPrefillWorkspace":
        tokens = int(tokens)
        if tokens < 0 or tokens > self.capacity_tokens:
            raise ValueError(
                f"workspace token capacity is {self.capacity_tokens}, requested {tokens}"
            )
        return PackedGatedDeltaPrefillWorkspace(
            query=active_token_prefix(self.query, tokens),
            key=active_token_prefix(self.key, tokens),
            value=active_token_prefix(self.value, tokens),
            out=active_token_prefix(self.out, tokens),
            log_g=active_token_prefix(self.log_g, tokens),
            beta_bf16=active_token_prefix(self.beta_bf16, tokens),
            beta_fp32=(
                active_token_prefix(self.beta_fp32, tokens)
                if self.beta_fp32 is not None
                else None
            ),
        )

    def can_serve(
        self,
        mixed_qkv: torch.Tensor,
        a: torch.Tensor,
        *,
        head_dim: int = 128,
    ) -> bool:
        if mixed_qkv.ndim != 3 or a.ndim != 3 or mixed_qkv.shape[:2] != a.shape[:2]:
            return False
        tokens = int(mixed_qkv.shape[1])
        num_v_heads = int(a.shape[2])
        qk_dim = int(mixed_qkv.shape[2]) - num_v_heads * head_dim
        if qk_dim <= 0 or qk_dim % (2 * head_dim):
            return False
        num_k_heads = qk_dim // (2 * head_dim)
        capacity = self.capacity_tokens
        tensors = (
            self.query,
            self.key,
            self.value,
            self.out,
            self.log_g,
            self.beta_bf16,
        )
        optional_tensors = (
            (self.beta_fp32, torch.float32),
        )
        return (
            capacity >= tokens
            and self.query.shape == (1, capacity, num_k_heads, head_dim)
            and self.key.shape == self.query.shape
            and self.value.shape == (1, capacity, num_v_heads, head_dim)
            and self.out.shape == self.value.shape
            and self.log_g.shape == (1, capacity, num_v_heads)
            and self.beta_bf16.shape == self.log_g.shape
            and self.query.dtype == mixed_qkv.dtype
            and self.key.dtype == mixed_qkv.dtype
            and self.value.dtype == mixed_qkv.dtype
            and self.out.dtype == mixed_qkv.dtype
            and self.beta_bf16.dtype == mixed_qkv.dtype
            and self.log_g.dtype == torch.float32
            and a.device == mixed_qkv.device
            and a.dtype == mixed_qkv.dtype
            and all(
                tensor.device == mixed_qkv.device and tensor.is_contiguous()
                for tensor in tensors
            )
            and all(
                tensor is None
                or (
                    tensor.shape == self.log_g.shape
                    and tensor.dtype == dtype
                    and tensor.device == mixed_qkv.device
                    and tensor.is_contiguous()
                )
                for tensor, dtype in optional_tensors
            )
        )


def allocate_packed_gated_delta_prefill_workspace(
    mixed_qkv: torch.Tensor,
    a: torch.Tensor,
    *,
    head_dim: int = 128,
    capacity_tokens: int | None = None,
) -> PackedGatedDeltaPrefillWorkspace:
    if mixed_qkv.ndim != 3 or mixed_qkv.shape[0] != 1:
        raise ValueError(
            f"mixed_qkv must be [1,T,F], got {tuple(mixed_qkv.shape)}"
        )
    if a.ndim != 3 or a.shape[:2] != mixed_qkv.shape[:2]:
        raise ValueError(f"a must be [1,T,V], got {tuple(a.shape)}")
    num_v_heads = int(a.shape[2])
    packed_dim = int(mixed_qkv.shape[2])
    qk_dim = packed_dim - num_v_heads * head_dim
    if qk_dim <= 0 or qk_dim % (2 * head_dim):
        raise ValueError(
            f"cannot infer GDN heads from packed_dim={packed_dim}, "
            f"num_v_heads={num_v_heads}, head_dim={head_dim}"
        )
    num_k_heads = qk_dim // (2 * head_dim)
    tokens = int(mixed_qkv.shape[1])
    capacity = (
        ((tokens + 63) // 64) * 64
        if capacity_tokens is None
        else int(capacity_tokens)
    )
    if capacity < tokens:
        raise ValueError(
            f"workspace capacity {capacity} is smaller than current tokens {tokens}"
        )
    device = mixed_qkv.device
    dtype = mixed_qkv.dtype
    query_shape = (1, capacity, num_k_heads, head_dim)
    value_shape = (1, capacity, num_v_heads, head_dim)
    gate_shape = (1, capacity, num_v_heads)
    beta_fp32 = None
    if mixed_qkv.is_cuda and torch.cuda.get_device_capability(mixed_qkv.device)[0] == 10:
        beta_fp32 = torch.empty(
            gate_shape,
            device=device,
            dtype=torch.float32,
        )
    return PackedGatedDeltaPrefillWorkspace(
        query=torch.empty(query_shape, device=device, dtype=dtype),
        key=torch.empty(query_shape, device=device, dtype=dtype),
        value=torch.empty(value_shape, device=device, dtype=dtype),
        out=torch.empty(value_shape, device=device, dtype=dtype),
        log_g=torch.empty(gate_shape, device=device, dtype=torch.float32),
        beta_bf16=torch.empty(gate_shape, device=device, dtype=dtype),
        beta_fp32=beta_fp32,
    )
